struct Counter {
    count: u32,
    limit: u32,
}

impl Counter {
    fn new(limit: u32) -> Self {
        Counter { count: 0, limit }
    }

    fn increment(&mut self) -> u32 {
        if self.count < self.limit {
            self.count += 1;
        }
        self.count
    }

    fn is_full(&self) -> bool {
        self.count == self.limit
    }
}

fn main() {
    let mut c = Counter::new(2);
    c.increment();
    c.increment();
    c.increment();
    println!("{} {}", c.count, c.is_full());
}

